// === Compute weekly time window (last 7 days, Mon UTC reference) ===
const now = new Date();
const weekEndUnix = Math.floor(now.getTime() / 1000);
const weekStartUnix = weekEndUnix - 7 * 24 * 3600;
const fmt = d => new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', year: 'numeric', month: 'short', day: 'numeric' }).format(d);
const startDate = fmt(new Date(weekStartUnix * 1000));
const endDate = fmt(new Date(weekEndUnix * 1000));
return [{ json: { weekStartUnix, weekEndUnix, startDate, endDate } }];

// === Fetch weekly conversation list + details, aggregate w/ failure + sentiment detail ===
const EL_API_KEY = 'REDACTED_api_key';
const ctx = $('Compute Time Range').item.json;
const { weekStartUnix, weekEndUnix, startDate, endDate } = ctx;
const CLINICS = [
  { label: 'Little Haiti', agent_id: 'agent_9601kr2e38r2f2btyjkyxtzearzh', phone: '+1 786 648 8256' },
  { label: 'North Miami',  agent_id: 'agent_1601kr6f47whfhq9yjj31e1epn6e', phone: '+1 786 938 5884' },
];
const headers = { 'xi-api-key': EL_API_KEY, 'Accept': 'application/json' };

async function listConvs(agent_id) {
  const all = []; let cursor = null;
  for (let p = 0; p < 8; p++) {
    let url = `https://api.elevenlabs.io/v1/convai/conversations?agent_id=${agent_id}&call_start_after_unix=${weekStartUnix}&call_start_before_unix=${weekEndUnix}&page_size=100`;
    if (cursor) url += `&cursor=${encodeURIComponent(cursor)}`;
    const res = await this.helpers.httpRequest({ method: 'GET', url, headers, json: true });
    const items = res.conversations || [];
    all.push(...items);
    cursor = res.next_cursor || res.cursor || null;
    if (!cursor || !res.has_more) break;
  }
  return all;
}
async function fetchDetail(conversation_id) {
  try { return await this.helpers.httpRequest({ method: 'GET', url: `https://api.elevenlabs.io/v1/convai/conversations/${conversation_id}`, headers, json: true }); }
  catch (e) { return null; }
}
function fmtDur(s) { if (!s) return '0s'; const m=Math.floor(s/60),x=s%60; return m>0?`${m}m ${x}s`:`${x}s`; }
function pct(n, t) { return t === 0 ? '0%' : `${Math.round(n/t*100)}%`; }
function escHtml(s) { return String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]); }
function fmtDate(unix) { return new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date((unix||0)*1000)); }

const NEG_SENTIMENTS = ['frustrated','angry','distressed','negative','upset'];

async function aggregateAllTime(clinic) {
  // Fetch ALL conversations (no time filter, capped at ~10 pages = 1000 calls).
  // Light analysis only — uses list endpoint, no per-call detail fetches.
  const all = []; let cursor = null;
  for (let p = 0; p < 10; p++) {
    let url = `https://api.elevenlabs.io/v1/convai/conversations?agent_id=${clinic.agent_id}&page_size=100`;
    if (cursor) url += `&cursor=${encodeURIComponent(cursor)}`;
    try {
      const res = await this.helpers.httpRequest({ method: 'GET', url, headers, json: true });
      const items = res.conversations || [];
      all.push(...items);
      cursor = res.next_cursor || res.cursor || null;
      if (!cursor || !res.has_more) break;
    } catch (e) { break; }
  }
  const total = all.length;
  if (total === 0) return { clinic, total: 0, totalMinutes: 0, successes: 0, failures: 0, firstCallDate: null, lastCallDate: null };
  const sumDur = all.reduce((a,c)=>a+(c.call_duration_secs||0), 0);
  const totalMinutes = Math.round(sumDur / 60);
  const successes = all.filter(c => c.call_successful === 'success').length;
  const failures = all.filter(c => c.call_successful === 'failure').length;
  const times = all.map(c => c.start_time_unix_secs).filter(Boolean).sort((a,b)=>a-b);
  const fmt = u => new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', year: 'numeric', month: 'short', day: 'numeric' }).format(new Date(u*1000));
  return { clinic, total, totalMinutes, successes, failures,
           firstCallDate: times.length > 0 ? fmt(times[0]) : null,
           lastCallDate: times.length > 0 ? fmt(times[times.length-1]) : null };
}

async function aggregate(clinic) {
  const list = await listConvs.call(this, clinic.agent_id);
  const total = list.length;
  if (total === 0) return { clinic, total: 0, list: [], failedDetails: [], negSentDetails: [], successes: 0, failures: 0, totalMinutes: 0, afterHours: 0, inHours: 0, intents: {}, outcomes: {}, sentiments: {}, veryShort: 0, veryLong: 0, sumDur: 0, avgDur: 0, minDur: 0, maxDur: 0, kreyolCalls: 0, switchedLanguage: 0, kreyolSuccessful: 0, kreyolFailed: 0 };

  const fetchCap = Math.min(total, 200);
  const details = [];
  for (let i = 0; i < fetchCap; i++) {
    const d = await fetchDetail.call(this, list[i].conversation_id);
    details.push(d);
  }

  // Aggregate
  const sumDur = list.reduce((a,c)=>a+(c.call_duration_secs||0), 0);
  const avgDur = Math.round(sumDur / total);
  const minDur = Math.min(...list.map(c=>c.call_duration_secs||0));
  const maxDur = Math.max(...list.map(c=>c.call_duration_secs||0));
  const totalMinutes = Math.round(sumDur / 60);
  const successes = list.filter(c => c.call_successful === 'success').length;
  const failures = list.filter(c => c.call_successful === 'failure').length;
  const veryShort = list.filter(c => (c.call_duration_secs||0) > 0 && (c.call_duration_secs||0) < 30).length;
  const veryLong = list.filter(c => (c.call_duration_secs||0) > 600).length;

  const intents = {}, outcomes = {}, sentiments = {};
  let afterHours = 0, inHours = 0;
  let kreyolCalls = 0;  // stayed in Kreyol
  let switchedLanguage = 0;  // caller spoke English/French/Spanish; agent invoked fallback
  let kreyolSuccessful = 0;
  let kreyolFailed = 0;
  const failedDetails = [];
  const negSentDetails = [];

  for (let i = 0; i < details.length; i++) {
    const d = details[i];
    if (!d) continue;
    const list_item = list[i] || {};
    const analysis = d.analysis || {};
    const dc = analysis.data_collection_results || {};
    const dyn = (d.conversation_initiation_client_data || {}).dynamic_variables || {};

    const intent = String((dc.routed_department && (dc.routed_department.value !== undefined ? dc.routed_department.value : dc.routed_department)) || '').toLowerCase();
    const outcome = String((dc.outcome && (dc.outcome.value !== undefined ? dc.outcome.value : dc.outcome)) || '').toLowerCase();
    const sentiment = String((dc.caller_sentiment && (dc.caller_sentiment.value !== undefined ? dc.caller_sentiment.value : dc.caller_sentiment)) || '').toLowerCase();

    if (intent) intents[intent] = (intents[intent] || 0) + 1;
    if (outcome) outcomes[outcome] = (outcomes[outcome] || 0) + 1;
    if (sentiment) sentiments[sentiment] = (sentiments[sentiment] || 0) + 1;

    const ah = String(dyn.is_after_hours || '').toLowerCase();
    if (ah === 'true') afterHours++; else inHours++;

    // === Language detection ===
    // Check transcript for language_detection tool invocations
    const transcript = d.transcript || [];
    let langSwitched = false;
    for (const turn of transcript) {
      const toolCalls = turn.tool_calls || [];
      for (const tc of toolCalls) {
        const toolName = tc.tool_name || tc.name || '';
        if (toolName === 'language_detection') {
          // language_detection fired = caller spoke non-Kreyol
          langSwitched = true;
          break;
        }
      }
      if (langSwitched) break;
    }
    if (langSwitched) {
      switchedLanguage++;
    } else {
      kreyolCalls++;
      if (list_item.call_successful === 'success') kreyolSuccessful++;
      else if (list_item.call_successful === 'failure') kreyolFailed++;
    }

    const callerName = `${dyn.caller_first_name || ''} ${dyn.caller_last_name || ''}`.trim() || (dyn.caller_phone ? dyn.caller_phone : 'unknown');
    const callerPhone = dyn.caller_phone || '';
    const dashUrl = `https://elevenlabs.io/app/conversational-ai/agents/${clinic.agent_id}/history/conversations/${list_item.conversation_id}`;
    const duration = fmtDur(list_item.call_duration_secs);
    const when = fmtDate(list_item.start_time_unix_secs);
    const summary = analysis.transcript_summary || '';

    // Build evaluation reasons (voice AI evaluator's rationale per criterion)
    const evalReasons = [];
    const ec = analysis.evaluation_criteria_results || {};
    for (const k of Object.keys(ec)) {
      const r = ec[k];
      if (r && r.result === 'failure') {
        evalReasons.push((r.rationale || '').toString().slice(0, 280));
      }
    }

    // Failed call detail entry
    if (list_item.call_successful === 'failure') {
      failedDetails.push({
        when, duration, callerName, callerPhone, intent, outcome, sentiment,
        summary, evalReasons, dashUrl,
      });
    }

    // Negative-sentiment detail entry (regardless of success)
    if (NEG_SENTIMENTS.includes(sentiment)) {
      negSentDetails.push({
        when, duration, callerName, callerPhone, intent, outcome, sentiment,
        summary, dashUrl,
      });
    }
  }

  return { clinic, total, list, sumDur, avgDur, minDur, maxDur, totalMinutes,
           successes, failures, veryShort, veryLong, intents, outcomes, sentiments,
           afterHours, inHours, failedDetails, negSentDetails,
           kreyolCalls, switchedLanguage, kreyolSuccessful, kreyolFailed };
}

function distRow(label, dist, color) {
  const entries = Object.entries(dist).sort((a,b)=>b[1]-a[1]);
  if (entries.length === 0) return '';
  const cells = entries.map(([k,v]) => {
    const tone = (color && color[k]) ? `color:${color[k]};` : '';
    return `<span style="display:inline-block;margin:2px 10px 2px 0;${tone}"><strong>${v}</strong> ${escHtml(k)}</span>`;
  }).join('');
  return `<tr><td style="padding:6px 12px;background:#f7f7f7;vertical-align:top">${label}</td><td style="padding:6px 12px">${cells}</td></tr>`;
}

function detailCard(d, isFailed) {
  const headerColor = isFailed ? '#c0392b' : '#d35400';
  const sentimentBadge = d.sentiment ? `<span style="background:#fee;color:#c0392b;padding:2px 6px;border-radius:3px;font-size:12px">${escHtml(d.sentiment)}</span>` : '';
  let html = `<div style="border-left:3px solid ${headerColor};padding:10px 14px;margin:10px 0;background:#fafafa">`;
  html += `<div style="font-size:13px;color:#666;margin-bottom:6px">`;
  html += `<strong style="color:#000">${escHtml(d.callerName)}</strong>`;
  if (d.callerPhone) html += ` · ${escHtml(d.callerPhone)}`;
  html += ` · ${escHtml(d.when)} · ${escHtml(d.duration)}`;
  if (d.intent) html += ` · intent: <strong>${escHtml(d.intent)}</strong>`;
  if (d.outcome) html += ` · outcome: <strong>${escHtml(d.outcome)}</strong>`;
  if (sentimentBadge) html += ` · ${sentimentBadge}`;
  html += '</div>';
  if (d.summary) html += `<div style="font-size:13px;color:#333;margin:6px 0">${escHtml(d.summary)}</div>`;
  if (d.evalReasons && d.evalReasons.length > 0) {
    html += '<div style="font-size:12px;color:#c0392b;margin-top:6px"><strong>Why flagged failed:</strong><ul style="margin:4px 0 0 0;padding-left:20px">';
    for (const r of d.evalReasons) html += `<li>${escHtml(r)}</li>`;
    html += '</ul></div>';
  }
  html += `<div style="font-size:12px;margin-top:8px"><a href="${d.dashUrl}" style="color:#0070f3">→ view call recording</a></div>`;
  html += '</div>';
  return html;
}

function clinicSection(s) {
  const c = s.clinic;
  if (s.total === 0) {
    return `<h2 style="color:#0070f3;margin-top:32px">${c.label} <span style="font-weight:normal;color:#888;font-size:14px">(${c.phone})</span></h2><p style="color:#888"><i>No calls received this week.</i></p>`;
  }
  const sentimentColor = { positive:'#27ae60', neutral:'#666', frustrated:'#e67e22', angry:'#c0392b', distressed:'#c0392b', negative:'#c0392b', upset:'#c0392b' };

  let html = `<h2 style="color:#0070f3;margin-top:32px">${c.label} <span style="font-weight:normal;color:#888;font-size:14px">(${c.phone})</span></h2>`;
  html += '<table style="border-collapse:collapse;margin:8px 0;width:100%">';
  html += `<tr><td style="padding:6px 12px;background:#f7f7f7;width:35%">Total calls</td><td style="padding:6px 12px"><strong>${s.total}</strong> (${s.totalMinutes} min total)</td></tr>`;
  html += `<tr><td style="padding:6px 12px;background:#f7f7f7">Avg / Min / Max duration</td><td style="padding:6px 12px">${fmtDur(s.avgDur)} · ${fmtDur(s.minDur)} · ${fmtDur(s.maxDur)}</td></tr>`;
  html += `<tr><td style="padding:6px 12px;background:#f7f7f7">In-hours / After-hours</td><td style="padding:6px 12px">${s.inHours} · ${s.afterHours} (${pct(s.afterHours, s.inHours+s.afterHours)} after-hours)</td></tr>`;
  html += `<tr><td style="padding:6px 12px;background:#f7f7f7"><strong style="color:#27ae60">Successful</strong> / <strong style="color:#c0392b">Failed</strong></td><td style="padding:6px 12px"><strong style="color:#27ae60">${s.successes}</strong> / <strong style="color:#c0392b">${s.failures}</strong> &nbsp;·&nbsp; ${pct(s.successes, s.total)} success</td></tr>`;
  html += distRow('Routed dept', s.intents);
  html += distRow('Outcome', s.outcomes);
  html += distRow('Caller sentiment', s.sentiments, sentimentColor);
  html += '</table>';

  // Anomalies
  const anomalies = [];
  if (s.veryShort > 0) anomalies.push(`<strong>${s.veryShort}</strong> calls under 30 sec`);
  if (s.veryLong > 0) anomalies.push(`<strong>${s.veryLong}</strong> calls over 10 min`);
  if (anomalies.length > 0) html += `<p style="margin:12px 0;color:#666;font-size:13px">Anomalies: ${anomalies.join(' · ')}</p>`;

  // FAILED CALLS DETAIL
  if (s.failedDetails.length > 0) {
    html += `<h3 style="color:#c0392b;margin-top:24px;margin-bottom:8px">⚠️ Failed calls — ${s.failedDetails.length} this week</h3>`;
    html += '<p style="color:#666;font-size:13px;margin:0 0 8px 0">Per-call detail. Click each to listen to the recording.</p>';
    for (const d of s.failedDetails.slice(0, 25)) {
      html += detailCard(d, true);
    }
    if (s.failedDetails.length > 25) html += `<p style="color:#888;font-size:13px"><i>(${s.failedDetails.length - 25} more in dashboard)</i></p>`;
  }

  // NEGATIVE-SENTIMENT CALLS (separate section even if not 'failed')
  const purelyNegative = s.negSentDetails.filter(d => !s.failedDetails.find(f => f.dashUrl === d.dashUrl));
  if (purelyNegative.length > 0) {
    html += `<h3 style="color:#e67e22;margin-top:24px;margin-bottom:8px">😟 Negative-sentiment calls (success but caller upset) — ${purelyNegative.length}</h3>`;
    html += '<p style="color:#666;font-size:13px;margin:0 0 8px 0">Caller sentiment was frustrated/angry/distressed but the agent\'s response was technically successful. Worth reviewing for patient experience.</p>';
    for (const d of purelyNegative.slice(0, 15)) {
      html += detailCard(d, false);
    }
    if (purelyNegative.length > 15) html += `<p style="color:#888;font-size:13px"><i>(${purelyNegative.length - 15} more in dashboard)</i></p>`;
  }

  return html;
}

const reports = [];
const allTimeReports = [];
for (const clinic of CLINICS) {
  reports.push(await aggregate.call(this, clinic));
  allTimeReports.push(await aggregateAllTime.call(this, clinic));
}

const totalCalls = reports.reduce((a,r)=>a+r.total, 0);
const totalMins  = reports.reduce((a,r)=>a+(r.totalMinutes||0), 0);
const totalAH    = reports.reduce((a,r)=>a+(r.afterHours||0), 0);
const totalFailed = reports.reduce((a,r)=>a+(r.failures||0), 0);
const totalNegSent = reports.reduce((a,r)=>a+r.negSentDetails.length, 0);
const totalKreyolCalls = reports.reduce((a,r)=>a+(r.kreyolCalls||0), 0);
const totalSwitched = reports.reduce((a,r)=>a+(r.switchedLanguage||0), 0);
const totalKreyolSuccessful = reports.reduce((a,r)=>a+(r.kreyolSuccessful||0), 0);
const totalKreyolFailed = reports.reduce((a,r)=>a+(r.kreyolFailed||0), 0);
const kreyolSuccessRate = totalKreyolCalls > 0 ? Math.round(totalKreyolSuccessful/totalKreyolCalls*100) : 0;

// All-time totals
const atTotal = allTimeReports.reduce((a,r)=>a+(r.total||0), 0);
const atMins = allTimeReports.reduce((a,r)=>a+(r.totalMinutes||0), 0);
const atSuccess = allTimeReports.reduce((a,r)=>a+(r.successes||0), 0);
const atFailed = allTimeReports.reduce((a,r)=>a+(r.failures||0), 0);
const atSuccessRate = atTotal > 0 ? Math.round(atSuccess/atTotal*100) : 0;
const atLHTotal = allTimeReports[0]?.total || 0;
const atNMTotal = allTimeReports[1]?.total || 0;
const atFirstDate = allTimeReports.flatMap(r => r.firstCallDate ? [r.firstCallDate] : [])[0] || 'N/A';

const html = `<!doctype html><html><body style="font-family:system-ui,-apple-system,sans-serif;color:#333;max-width:760px;margin:24px auto;padding:0 24px;line-height:1.55">
<h1 style="color:#000;margin-bottom:4px">Medisun Voice AI — Weekly Report</h1>
<p style="color:#666;margin-top:0">Week of ${startDate} – ${endDate}</p>

<div style="background:#f0f9f4;border-left:4px solid #27ae60;padding:14px 18px;margin:24px 0;border-radius:2px">
  <div style="font-weight:600;font-size:14px;color:#27ae60;margin-bottom:6px">📊 ALL TIME — both Kreyol agents (since ${atFirstDate})</div>
  <div style="font-size:18px;margin-bottom:2px"><strong>${atTotal}</strong> total calls · <strong>${atMins}</strong> minutes</div>
  <div style="font-size:14px">
    <span style="color:#27ae60"><strong>${atSuccess}</strong> successful</span>
    &nbsp;·&nbsp;
    <span style="color:#c0392b"><strong>${atFailed}</strong> failed</span>
    &nbsp;·&nbsp;
    <strong style="color:${atSuccessRate >= 90 ? '#27ae60' : atSuccessRate >= 70 ? '#e67e22' : '#c0392b'}">${atSuccessRate}%</strong> success rate
  </div>
  <div style="color:#666;font-size:13px;margin-top:6px">Little Haiti: ${atLHTotal} · North Miami: ${atNMTotal}</div>
</div>

<div style="background:#fffbed;border-left:4px solid #d35400;padding:14px 18px;margin:24px 0;border-radius:2px">
  <div style="font-weight:600;font-size:16px;color:#d35400;margin-bottom:8px">🇭🇹 Kreyol Performance (both clinics)</div>
  <div style="font-size:18px;margin-bottom:4px"><strong>${totalKreyolCalls}</strong> calls answered in Kreyol</div>
  <div style="font-size:14px">
    <span style="color:#27ae60"><strong>${totalKreyolSuccessful}</strong> successful</span>
    &nbsp;·&nbsp;
    <span style="color:#c0392b"><strong>${totalKreyolFailed}</strong> failed</span>
    &nbsp;·&nbsp;
    <strong style="color:${kreyolSuccessRate >= 90 ? '#27ae60' : kreyolSuccessRate >= 70 ? '#e67e22' : '#c0392b'}">${kreyolSuccessRate}%</strong> success rate
  </div>
  ${totalSwitched > 0 ? `<div style="color:#666;font-size:13px;margin-top:6px">+ <strong>${totalSwitched}</strong> calls where caller spoke another language (multilingual fallback triggered)</div>` : ''}
</div>

<div style="background:#f4f8ff;border-left:4px solid #0070f3;padding:14px 18px;margin:24px 0;border-radius:2px">
  <div style="font-weight:600;font-size:14px;color:#0070f3;margin-bottom:6px">All calls (any language)</div>
  <div style="font-size:14px"><strong>${totalCalls}</strong> total · <strong>${totalMins}</strong> min · <strong>${totalAH}</strong> after-hours</div>
  <div style="font-size:13px;margin-top:4px">
    <span style="color:#27ae60">${totalCalls - totalFailed} successful</span>
    &nbsp;·&nbsp;
    <span style="color:#c0392b">${totalFailed} failed</span>
    &nbsp;·&nbsp;
    <span style="color:#e67e22">${totalNegSent} negative sentiment</span>
  </div>
  <div style="color:#666;font-size:13px;margin-top:6px">Little Haiti: ${reports[0].total} · North Miami: ${reports[1].total}</div>
</div>

${clinicSection(reports[0])}
${clinicSection(reports[1])}

<hr style="border:none;border-top:1px solid #eee;margin:32px 0">
<p style="color:#888;font-size:13px">
  Internal Medisun Voice AI weekly report — automated.<br>

  Report ID: medisun-weekly-report
</p>
</body></html>`;

const subject = `Medisun Voice AI Weekly — ${startDate} to ${endDate} — ${totalKreyolCalls} Kreyol calls (${kreyolSuccessRate}% success, ${totalKreyolFailed} failed)`;
return [{ json: { emailSubject: subject, emailHtml: html, totalCalls, totalFailed, totalNegSent, totalMins, totalKreyolCalls, totalKreyolSuccessful, totalKreyolFailed, kreyolSuccessRate, totalSwitched, atTotal, atMins, atSuccess, atFailed, atSuccessRate, weekRange: `${startDate} to ${endDate}` } }];

// === Compute weekly time window (last 7 days, Mon UTC reference) ===
const now = new Date();
const weekEndUnix = Math.floor(now.getTime() / 1000);
const weekStartUnix = weekEndUnix - 7 * 24 * 3600;
const fmt = d => new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', year: 'numeric', month: 'short', day: 'numeric' }).format(d);
const startDate = fmt(new Date(weekStartUnix * 1000));
const endDate = fmt(new Date(weekEndUnix * 1000));
return [{ json: { weekStartUnix, weekEndUnix, startDate, endDate } }];

// === Fetch weekly conversation list + details, aggregate w/ failure + sentiment detail ===
const EL_API_KEY = 'REDACTED_api_key';
const ctx = $('Compute Time Range').item.json;
const { weekStartUnix, weekEndUnix, startDate, endDate } = ctx;
const CLINICS = [
  { label: 'Little Haiti', agent_id: 'agent_9601kr2e38r2f2btyjkyxtzearzh', phone: '+1 786 648 8256' },
  { label: 'North Miami',  agent_id: 'agent_1601kr6f47whfhq9yjj31e1epn6e', phone: '+1 786 938 5884' },
];
const headers = { 'xi-api-key': EL_API_KEY, 'Accept': 'application/json' };

async function listConvs(agent_id) {
  const all = []; let cursor = null;
  for (let p = 0; p < 8; p++) {
    let url = `https://api.elevenlabs.io/v1/convai/conversations?agent_id=${agent_id}&call_start_after_unix=${weekStartUnix}&call_start_before_unix=${weekEndUnix}&page_size=100`;
    if (cursor) url += `&cursor=${encodeURIComponent(cursor)}`;
    const res = await this.helpers.httpRequest({ method: 'GET', url, headers, json: true });
    const items = res.conversations || [];
    all.push(...items);
    cursor = res.next_cursor || res.cursor || null;
    if (!cursor || !res.has_more) break;
  }
  return all;
}
async function fetchDetail(conversation_id) {
  try { return await this.helpers.httpRequest({ method: 'GET', url: `https://api.elevenlabs.io/v1/convai/conversations/${conversation_id}`, headers, json: true }); }
  catch (e) { return null; }
}
function fmtDur(s) { if (!s) return '0s'; const m=Math.floor(s/60),x=s%60; return m>0?`${m}m ${x}s`:`${x}s`; }
function pct(n, t) { return t === 0 ? '0%' : `${Math.round(n/t*100)}%`; }
function escHtml(s) { return String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]); }
function fmtDate(unix) { return new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date((unix||0)*1000)); }

const NEG_SENTIMENTS = ['frustrated','angry','distressed','negative','upset'];

async function aggregateAllTime(clinic) {
  // Fetch ALL conversations (no time filter, capped at ~10 pages = 1000 calls).
  // Light analysis only — uses list endpoint, no per-call detail fetches.
  const all = []; let cursor = null;
  for (let p = 0; p < 10; p++) {
    let url = `https://api.elevenlabs.io/v1/convai/conversations?agent_id=${clinic.agent_id}&page_size=100`;
    if (cursor) url += `&cursor=${encodeURIComponent(cursor)}`;
    try {
      const res = await this.helpers.httpRequest({ method: 'GET', url, headers, json: true });
      const items = res.conversations || [];
      all.push(...items);
      cursor = res.next_cursor || res.cursor || null;
      if (!cursor || !res.has_more) break;
    } catch (e) { break; }
  }
  const total = all.length;
  if (total === 0) return { clinic, total: 0, totalMinutes: 0, successes: 0, failures: 0, firstCallDate: null, lastCallDate: null };
  const sumDur = all.reduce((a,c)=>a+(c.call_duration_secs||0), 0);
  const totalMinutes = Math.round(sumDur / 60);
  const successes = all.filter(c => c.call_successful === 'success').length;
  const failures = all.filter(c => c.call_successful === 'failure').length;
  const times = all.map(c => c.start_time_unix_secs).filter(Boolean).sort((a,b)=>a-b);
  const fmt = u => new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', year: 'numeric', month: 'short', day: 'numeric' }).format(new Date(u*1000));
  return { clinic, total, totalMinutes, successes, failures,
           firstCallDate: times.length > 0 ? fmt(times[0]) : null,
           lastCallDate: times.length > 0 ? fmt(times[times.length-1]) : null };
}

async function aggregate(clinic) {
  const list = await listConvs.call(this, clinic.agent_id);
  const total = list.length;
  if (total === 0) return { clinic, total: 0, list: [], failedDetails: [], negSentDetails: [], successes: 0, failures: 0, totalMinutes: 0, afterHours: 0, inHours: 0, intents: {}, outcomes: {}, sentiments: {}, veryShort: 0, veryLong: 0, sumDur: 0, avgDur: 0, minDur: 0, maxDur: 0, kreyolCalls: 0, switchedLanguage: 0, kreyolSuccessful: 0, kreyolFailed: 0 };

  const fetchCap = Math.min(total, 200);
  const details = [];
  for (let i = 0; i < fetchCap; i++) {
    const d = await fetchDetail.call(this, list[i].conversation_id);
    details.push(d);
  }

  // Aggregate
  const sumDur = list.reduce((a,c)=>a+(c.call_duration_secs||0), 0);
  const avgDur = Math.round(sumDur / total);
  const minDur = Math.min(...list.map(c=>c.call_duration_secs||0));
  const maxDur = Math.max(...list.map(c=>c.call_duration_secs||0));
  const totalMinutes = Math.round(sumDur / 60);
  const successes = list.filter(c => c.call_successful === 'success').length;
  const failures = list.filter(c => c.call_successful === 'failure').length;
  const veryShort = list.filter(c => (c.call_duration_secs||0) > 0 && (c.call_duration_secs||0) < 30).length;
  const veryLong = list.filter(c => (c.call_duration_secs||0) > 600).length;

  const intents = {}, outcomes = {}, sentiments = {};
  let afterHours = 0, inHours = 0;
  let kreyolCalls = 0;  // stayed in Kreyol
  let switchedLanguage = 0;  // caller spoke English/French/Spanish; agent invoked fallback
  let kreyolSuccessful = 0;
  let kreyolFailed = 0;
  const failedDetails = [];
  const negSentDetails = [];

  for (let i = 0; i < details.length; i++) {
    const d = details[i];
    if (!d) continue;
    const list_item = list[i] || {};
    const analysis = d.analysis || {};
    const dc = analysis.data_collection_results || {};
    const dyn = (d.conversation_initiation_client_data || {}).dynamic_variables || {};

    const intent = String((dc.routed_department && (dc.routed_department.value !== undefined ? dc.routed_department.value : dc.routed_department)) || '').toLowerCase();
    const outcome = String((dc.outcome && (dc.outcome.value !== undefined ? dc.outcome.value : dc.outcome)) || '').toLowerCase();
    const sentiment = String((dc.caller_sentiment && (dc.caller_sentiment.value !== undefined ? dc.caller_sentiment.value : dc.caller_sentiment)) || '').toLowerCase();

    if (intent) intents[intent] = (intents[intent] || 0) + 1;
    if (outcome) outcomes[outcome] = (outcomes[outcome] || 0) + 1;
    if (sentiment) sentiments[sentiment] = (sentiments[sentiment] || 0) + 1;

    const ah = String(dyn.is_after_hours || '').toLowerCase();
    if (ah === 'true') afterHours++; else inHours++;

    // === Language detection ===
    // Check transcript for language_detection tool invocations
    const transcript = d.transcript || [];
    let langSwitched = false;
    for (const turn of transcript) {
      const toolCalls = turn.tool_calls || [];
      for (const tc of toolCalls) {
        const toolName = tc.tool_name || tc.name || '';
        if (toolName === 'language_detection') {
          // language_detection fired = caller spoke non-Kreyol
          langSwitched = true;
          break;
        }
      }
      if (langSwitched) break;
    }
    if (langSwitched) {
      switchedLanguage++;
    } else {
      kreyolCalls++;
      if (list_item.call_successful === 'success') kreyolSuccessful++;
      else if (list_item.call_successful === 'failure') kreyolFailed++;
    }

    const callerName = `${dyn.caller_first_name || ''} ${dyn.caller_last_name || ''}`.trim() || (dyn.caller_phone ? dyn.caller_phone : 'unknown');
    const callerPhone = dyn.caller_phone || '';
    const dashUrl = `https://elevenlabs.io/app/conversational-ai/agents/${clinic.agent_id}/history/conversations/${list_item.conversation_id}`;
    const duration = fmtDur(list_item.call_duration_secs);
    const when = fmtDate(list_item.start_time_unix_secs);
    const summary = analysis.transcript_summary || '';

    // Build evaluation reasons (voice AI evaluator's rationale per criterion)
    const evalReasons = [];
    const ec = analysis.evaluation_criteria_results || {};
    for (const k of Object.keys(ec)) {
      const r = ec[k];
      if (r && r.result === 'failure') {
        evalReasons.push((r.rationale || '').toString().slice(0, 280));
      }
    }

    // Failed call detail entry
    if (list_item.call_successful === 'failure') {
      failedDetails.push({
        when, duration, callerName, callerPhone, intent, outcome, sentiment,
        summary, evalReasons, dashUrl,
      });
    }

    // Negative-sentiment detail entry (regardless of success)
    if (NEG_SENTIMENTS.includes(sentiment)) {
      negSentDetails.push({
        when, duration, callerName, callerPhone, intent, outcome, sentiment,
        summary, dashUrl,
      });
    }
  }

  return { clinic, total, list, sumDur, avgDur, minDur, maxDur, totalMinutes,
           successes, failures, veryShort, veryLong, intents, outcomes, sentiments,
           afterHours, inHours, failedDetails, negSentDetails,
           kreyolCalls, switchedLanguage, kreyolSuccessful, kreyolFailed };
}

function distRow(label, dist, color) {
  const entries = Object.entries(dist).sort((a,b)=>b[1]-a[1]);
  if (entries.length === 0) return '';
  const cells = entries.map(([k,v]) => {
    const tone = (color && color[k]) ? `color:${color[k]};` : '';
    return `<span style="display:inline-block;margin:2px 10px 2px 0;${tone}"><strong>${v}</strong> ${escHtml(k)}</span>`;
  }).join('');
  return `<tr><td style="padding:6px 12px;background:#f7f7f7;vertical-align:top">${label}</td><td style="padding:6px 12px">${cells}</td></tr>`;
}

function detailCard(d, isFailed) {
  const headerColor = isFailed ? '#c0392b' : '#d35400';
  const sentimentBadge = d.sentiment ? `<span style="background:#fee;color:#c0392b;padding:2px 6px;border-radius:3px;font-size:12px">${escHtml(d.sentiment)}</span>` : '';
  let html = `<div style="border-left:3px solid ${headerColor};padding:10px 14px;margin:10px 0;background:#fafafa">`;
  html += `<div style="font-size:13px;color:#666;margin-bottom:6px">`;
  html += `<strong style="color:#000">${escHtml(d.callerName)}</strong>`;
  if (d.callerPhone) html += ` · ${escHtml(d.callerPhone)}`;
  html += ` · ${escHtml(d.when)} · ${escHtml(d.duration)}`;
  if (d.intent) html += ` · intent: <strong>${escHtml(d.intent)}</strong>`;
  if (d.outcome) html += ` · outcome: <strong>${escHtml(d.outcome)}</strong>`;
  if (sentimentBadge) html += ` · ${sentimentBadge}`;
  html += '</div>';
  if (d.summary) html += `<div style="font-size:13px;color:#333;margin:6px 0">${escHtml(d.summary)}</div>`;
  if (d.evalReasons && d.evalReasons.length > 0) {
    html += '<div style="font-size:12px;color:#c0392b;margin-top:6px"><strong>Why flagged failed:</strong><ul style="margin:4px 0 0 0;padding-left:20px">';
    for (const r of d.evalReasons) html += `<li>${escHtml(r)}</li>`;
    html += '</ul></div>';
  }
  html += `<div style="font-size:12px;margin-top:8px"><a href="${d.dashUrl}" style="color:#0070f3">→ view call recording</a></div>`;
  html += '</div>';
  return html;
}

function clinicSection(s) {
  const c = s.clinic;
  if (s.total === 0) {
    return `<h2 style="color:#0070f3;margin-top:32px">${c.label} <span style="font-weight:normal;color:#888;font-size:14px">(${c.phone})</span></h2><p style="color:#888"><i>No calls received this week.</i></p>`;
  }
  const sentimentColor = { positive:'#27ae60', neutral:'#666', frustrated:'#e67e22', angry:'#c0392b', distressed:'#c0392b', negative:'#c0392b', upset:'#c0392b' };

  let html = `<h2 style="color:#0070f3;margin-top:32px">${c.label} <span style="font-weight:normal;color:#888;font-size:14px">(${c.phone})</span></h2>`;
  html += '<table style="border-collapse:collapse;margin:8px 0;width:100%">';
  html += `<tr><td style="padding:6px 12px;background:#f7f7f7;width:35%">Total calls</td><td style="padding:6px 12px"><strong>${s.total}</strong> (${s.totalMinutes} min total)</td></tr>`;
  html += `<tr><td style="padding:6px 12px;background:#f7f7f7">Avg / Min / Max duration</td><td style="padding:6px 12px">${fmtDur(s.avgDur)} · ${fmtDur(s.minDur)} · ${fmtDur(s.maxDur)}</td></tr>`;
  html += `<tr><td style="padding:6px 12px;background:#f7f7f7">In-hours / After-hours</td><td style="padding:6px 12px">${s.inHours} · ${s.afterHours} (${pct(s.afterHours, s.inHours+s.afterHours)} after-hours)</td></tr>`;
  html += `<tr><td style="padding:6px 12px;background:#f7f7f7"><strong style="color:#27ae60">Successful</strong> / <strong style="color:#c0392b">Failed</strong></td><td style="padding:6px 12px"><strong style="color:#27ae60">${s.successes}</strong> / <strong style="color:#c0392b">${s.failures}</strong> &nbsp;·&nbsp; ${pct(s.successes, s.total)} success</td></tr>`;
  html += distRow('Routed dept', s.intents);
  html += distRow('Outcome', s.outcomes);
  html += distRow('Caller sentiment', s.sentiments, sentimentColor);
  html += '</table>';

  // Anomalies
  const anomalies = [];
  if (s.veryShort > 0) anomalies.push(`<strong>${s.veryShort}</strong> calls under 30 sec`);
  if (s.veryLong > 0) anomalies.push(`<strong>${s.veryLong}</strong> calls over 10 min`);
  if (anomalies.length > 0) html += `<p style="margin:12px 0;color:#666;font-size:13px">Anomalies: ${anomalies.join(' · ')}</p>`;

  // FAILED CALLS DETAIL
  if (s.failedDetails.length > 0) {
    html += `<h3 style="color:#c0392b;margin-top:24px;margin-bottom:8px">⚠️ Failed calls — ${s.failedDetails.length} this week</h3>`;
    html += '<p style="color:#666;font-size:13px;margin:0 0 8px 0">Per-call detail. Click each to listen to the recording.</p>';
    for (const d of s.failedDetails.slice(0, 25)) {
      html += detailCard(d, true);
    }
    if (s.failedDetails.length > 25) html += `<p style="color:#888;font-size:13px"><i>(${s.failedDetails.length - 25} more in dashboard)</i></p>`;
  }

  // NEGATIVE-SENTIMENT CALLS (separate section even if not 'failed')
  const purelyNegative = s.negSentDetails.filter(d => !s.failedDetails.find(f => f.dashUrl === d.dashUrl));
  if (purelyNegative.length > 0) {
    html += `<h3 style="color:#e67e22;margin-top:24px;margin-bottom:8px">😟 Negative-sentiment calls (success but caller upset) — ${purelyNegative.length}</h3>`;
    html += '<p style="color:#666;font-size:13px;margin:0 0 8px 0">Caller sentiment was frustrated/angry/distressed but the agent\'s response was technically successful. Worth reviewing for patient experience.</p>';
    for (const d of purelyNegative.slice(0, 15)) {
      html += detailCard(d, false);
    }
    if (purelyNegative.length > 15) html += `<p style="color:#888;font-size:13px"><i>(${purelyNegative.length - 15} more in dashboard)</i></p>`;
  }

  return html;
}

const reports = [];
const allTimeReports = [];
for (const clinic of CLINICS) {
  reports.push(await aggregate.call(this, clinic));
  allTimeReports.push(await aggregateAllTime.call(this, clinic));
}

const totalCalls = reports.reduce((a,r)=>a+r.total, 0);
const totalMins  = reports.reduce((a,r)=>a+(r.totalMinutes||0), 0);
const totalAH    = reports.reduce((a,r)=>a+(r.afterHours||0), 0);
const totalFailed = reports.reduce((a,r)=>a+(r.failures||0), 0);
const totalNegSent = reports.reduce((a,r)=>a+r.negSentDetails.length, 0);
const totalKreyolCalls = reports.reduce((a,r)=>a+(r.kreyolCalls||0), 0);
const totalSwitched = reports.reduce((a,r)=>a+(r.switchedLanguage||0), 0);
const totalKreyolSuccessful = reports.reduce((a,r)=>a+(r.kreyolSuccessful||0), 0);
const totalKreyolFailed = reports.reduce((a,r)=>a+(r.kreyolFailed||0), 0);
const kreyolSuccessRate = totalKreyolCalls > 0 ? Math.round(totalKreyolSuccessful/totalKreyolCalls*100) : 0;

// All-time totals
const atTotal = allTimeReports.reduce((a,r)=>a+(r.total||0), 0);
const atMins = allTimeReports.reduce((a,r)=>a+(r.totalMinutes||0), 0);
const atSuccess = allTimeReports.reduce((a,r)=>a+(r.successes||0), 0);
const atFailed = allTimeReports.reduce((a,r)=>a+(r.failures||0), 0);
const atSuccessRate = atTotal > 0 ? Math.round(atSuccess/atTotal*100) : 0;
const atLHTotal = allTimeReports[0]?.total || 0;
const atNMTotal = allTimeReports[1]?.total || 0;
const atFirstDate = allTimeReports.flatMap(r => r.firstCallDate ? [r.firstCallDate] : [])[0] || 'N/A';

const html = `<!doctype html><html><body style="font-family:system-ui,-apple-system,sans-serif;color:#333;max-width:760px;margin:24px auto;padding:0 24px;line-height:1.55">
<h1 style="color:#000;margin-bottom:4px">Medisun Voice AI — Weekly Report</h1>
<p style="color:#666;margin-top:0">Week of ${startDate} – ${endDate}</p>

<div style="background:#f0f9f4;border-left:4px solid #27ae60;padding:14px 18px;margin:24px 0;border-radius:2px">
